// The labels below are copy too: plain strings, so titles and
// breadcrumbs built from them have no markup and no stray whitespace.

func stateText(s TaskState) string {
	switch s {
	case StateActive:
		return "Active"
	case StateAggregating:
		return "Aggregating"
	case StateScheduled:
		return "Scheduled"
	case StateRetry:
		return "Retry"
	case StateArchived:
		return "Archived"
	case StateCompleted:
		return "Completed"
	}
	return "Pending"
}

// verbText is a verb's button label, or its "all" variant's.
func verbText(v TaskVerb, all bool) string {
	switch {
	case all && v == TaskRun:
		return "Run all"
	case all && v == TaskArchive:
		return "Archive all"
	case all:
		return "Delete all"
	case v == TaskRun:
		return "Run now"
	case v == TaskArchive:
		return "Archive"
	case v == TaskCancel:
		return "Cancel"
	}
	return "Delete"
}

// allTitleText is the "all" confirmation's title as plain text: the
// confirmation page's heading, title and breadcrumb.
func allTitleText(v TaskVerb, s TaskState, total int64) string {
	return verbText(v, true) + " " + format.Number(total) + " " + scopeTasks(s, "", total)
}

func tasksWord(n int64) string {
	if n == 1 {
		return "task"
	}
	return "tasks"
}

func noticeString(n TaskNotice) string {
	count := format.Number(n.Count) + " " + tasksWord(n.Count)
	switch n.Verb {
	case TaskRun:
		return "Moved " + count + " to pending"
	case TaskArchive:
		return "Archived " + count
	case TaskCancel:
		return "Cancel requested for " + count
	}
	return "Deleted " + count
}

